Here's a Python function that takes a string and returns the most frequent character:

```python
def most_frequent_char(s):
    """Return the most frequent character in a string."""
    from collections import Counter
    if not s:
        return None
    counts = Counter(s)
    # Return the character with the highest count
    return max(counts, key=counts.get)

# Example usage:
text = 'hello world'
print(most_frequent_char(text))  # 'l'

# Alternative without Counter:
def most_frequent_char_v2(s):
    if not s:
        return None
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return max(freq, key=freq.get)

# Return both char and count:
def most_frequent_char_with_count(s):
    if not s:
        return None, 0
    from collections import Counter
    char, count = Counter(s).most_common(1)[0]
    return char, count
```

All versions handle empty strings by returning None. The Counter approach is the most Pythonic, while the dictionary approach avoids imports.
